MOTIF_NAME = 'stm_attacks_hanging_opp_king_neighbor'
MOTIF_DESCRIPTION = 'The side to move has at least one legal, non-sacrificial check or capture on a square adjacent to the opponent king.'
def motif(fen: str) -> bool:
    import chess
    b = chess.Board(fen)
    stm = b.turn
    opp = not stm
    VAL = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 100}
    oksq = b.king(opp)
    if oksq is None:
        return False
    king_file = chess.square_file(oksq)
    king_rank = chess.square_rank(oksq)
    neighbors = []
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = king_file + df
            nr = king_rank + dr
            if 0 <= nf < 8 and 0 <= nr < 8:
                neighbors.append(chess.square(nf, nr))
    opp_attackers_total = 0
    for n in neighbors:
        opp_attackers_total += len(b.attackers(opp, n))
    for mv in b.legal_moves:
        to = mv.to_square
        atk = b.piece_at(mv.from_square)
        if atk is None or atk.piece_type == chess.KING:
            continue
        if to not in neighbors:
            continue
        av = VAL[atk.piece_type]
        capture = b.is_capture(mv)
        dest_defended = bool(b.attackers(opp, to))
        safe = True
        consumed = set()
        # roughly safe if undefended target is a pawn and attacker value <= 3, or target value+2 >= attacker value, or square undefended by non-pawn
        if capture:
            tp = b.piece_at(to)
            if tp is not None:
                tv = VAL.get(tp.piece_type, 0)
                if dest_defended and av > tv:
                    # sacrifice unless a friendly non-pawn can recapture cheaply by value
                    rcok = False
                    ra_count = 0
                    for r in b.attackers(stm, to):
                        rp = b.piece_at(r)
                        if rp is None or r == mv.from_square:
                            continue
                        if rp.piece_type != chess.KING and VAL[rp.piece_type] <= av:
                            rcok = True
                            break
                        ra_count += 1
                    if not rcok:
                        safe = False
            elif dest_defended:
                safe = False
        else:
            if dest_defended:
                # quiet move to defended king-neighbor square is risky unless cheap piece
                if av >= 3:
                    safe = False
        if safe:
            return True
    return False
